<script setup lang="ts">
import {FileText,CheckCircle2,AlertTriangle,LoaderCircle,ChevronRight} from 'lucide-vue-next'
import {computed} from 'vue'
import {traceRows} from '../paymentTraceRows'
import {date,type Row} from '../lib'
const props=defineProps<{events:Row[];live?:boolean;filter?:string}>()
const rows=computed(()=>traceRows(props.events,!!props.live).filter(e=>!props.filter||props.filter==='all'||props.filter==='attention'&&(e.raw.some((r:Row)=>['failed','review'].includes(r.state)||r.http_status>=400))||props.filter==='network'&&(e.phase==='network'||e.diagnostics?.request_kind)))
const statusLabel:Record<string,string>={running:'进行中',completed:'完成',failed:'失败',review:'待核实',waiting:'等待',recorded:'已记录'}
const requestLabels:Record<string,string>={exit_probe:'检查网络出口',checkout_create:'请求生成结账链接',checkout_initialize:'初始化结账页面',session_read:'读取官方登录态',account_read:'读取订阅账号',subscription_read:'查询订阅状态'}
const eventLabel=(e:Row)=>e.displayLabel||requestLabels[e.diagnostics?.request_kind]|| (e.diagnostics?.page_event?'商户回跳页面':e.diagnostics?.sdk_request?'官方验证资源':e.phase==='confirming'?'提交付款请求':e.label)
const eventStatus=(e:Row)=>e.spinning?'进行中':e.displayState==='recorded'?'已记录':e.http_status&&e.state==='completed'?'已返回':e.diagnostics?.page_event?(e.diagnostics.page_event==='approval_not_requested'?'尚未发起批准':['request_failed','request_blocked','script_error'].includes(e.diagnostics.page_event)?'页面异常':e.http_status>=400?'请求被拒绝':'已记录'):e.diagnostics?.sdk_waiting||e.diagnostics?.sdk_issue==='resource_pending'?'等待中':e.diagnostics?.sdk_event==='network'?'资源已返回':e.diagnostics?.sdk_issue==='resource_failed'||e.diagnostics?.sdk_issue==='resource_http_error'?'资源失败':e.phase==='confirming'&&e.state==='completed'?'请求已返回':statusLabel[e.displayState]||e.displayState
const diagnosticLabels:Record<string,string>={post_payment_delay_seconds:'付款后等待配置（秒）',post_payment_wait_ms:'本次等待（毫秒）',page_event:'回跳页面事件',page_host:'页面资源域名',page_route:'页面类型',page_resource:'资源类型',page_auth:'登录信息字段',page_network_error:'浏览器错误码',sdk_connect_ms:'资源连接耗时',sdk_tls_ms:'资源握手耗时',sdk_response_ms:'资源响应等待',sdk_host:'资源域名',sdk_route:'资源路径类型',sdk_resource_key:'资源关联标识',sdk_method:'请求方法',sdk_request_type:'浏览器请求类型',sdk_network_error:'浏览器错误码',sdk_request:'请求序号',sdk_requests:'已发起请求',sdk_completed:'已完成请求',sdk_failed:'失败请求',sdk_pending:'仍在等待请求',sdk_duration_ms:'资源请求耗时',sdk_guard_ms:'出口检查耗时',sdk_stage:'验证阶段',sdk_resource:'资源类型',sdk_event:'记录类型',sdk_issue:'异常原因',sdk_wait_ms:'本阶段等待',sdk_waiting:'仍在等待',sdk_outcome:'SDK 处理结果',sdk_code:'SDK 诊断码',diagnostic_source:'状态来源',payment_state:'付款状态',raw_status:'原交易状态',raw_state:'原流程状态',raw_payment_status:'原付款状态',next_action_type:'后续验证类型',sdk_action_type:'SDK 验证类型',sdk_has_stripe_js:'提供 SDK 验证入口',sdk_has_3ds_source:'提供 3DS 资源',dns_ms:'域名解析',connect_ms:'建立连接',tls_ms:'安全握手',first_byte_ms:'等待首字节',connection_ready_ms:'通道就绪',request_write_ms:'请求发送',response_wait_ms:'响应等待',network_stage_elapsed_ms:'网络阶段耗时',request_attempt:'请求尝试次数',network_stage:'网络阶段',protocol_code:'流程诊断码',network_reason:'网络原因',provider_code:'上游错误码',decline_code:'拒付分类',response_kind:'响应类型'}
const diagnosticValues:Record<string,string>={navigated:'页面已跳转',dom_ready:'页面结构已加载',script_error:'页面脚本异常',response:'页面请求已返回',resource_loaded:'脚本资源已加载',request_failed:'页面请求失败',request_blocked:'请求被允许域名规则拦截',auth_observed:'登录信息已读取',approval_observed:'批准请求已进入授权检查',approval_not_requested:'未观察到商户批准请求',merchant_return:'商户回跳',auth_session:'登录信息',login:'登录页面',checkout:'结账页面',present:'包含登录信息',missing:'未包含登录信息',unknown:'尚未确认',resource_completed:'资源读取完成',resource_pending:'资源请求尚未返回',network:'网络请求',stripe_v3:'Stripe SDK 主脚本',stripe_basil:'Stripe Basil 脚本',payment_intent:'原付款状态查询',three_ds:'3DS 资源',static_asset:'静态资源',browser_start:'启动验证浏览器',page_loading:'加载官方 SDK',sdk_loaded:'SDK 页面脚本就绪',context_ready:'原交易上下文就绪',preflight:'SDK 正在预查原交易',preflight_returned:'原交易预查已返回',preflight_error:'原交易预查异常',sdk_action:'等待官方验证返回',sdk_returned:'官方验证已返回',sdk_exception:'官方验证调用异常',notifying:'回传验证结果',progress:'进展',diagnostic:'诊断',sdk_script:'SDK 主脚本',sdk_frame:'SDK 资源',processor_api:'支付状态接口',verification_resource:'验证资源',resource_failed:'资源加载失败',resource_http_error:'资源返回错误',guard_timeout:'出口检查响应超时',csp_blocked:'资源被页面策略拦截',page_error:'页面脚本异常',timeout:'超时',proxy_connect:'代理隧道连接失败',tls:'安全握手失败',dns:'域名解析失败',connection:'建立连接',request_write:'发送请求',response_headers:'等待响应头',response_body:'读取响应内容',json:'JSON',html:'HTML 页面',empty:'空响应',other:'其他格式'}
Object.assign(requestLabels,{payment_method_create:'创建银行卡付款方式',payment_token_create:'创建付款令牌',payment_confirm:'提交付款确认',payment_read:'读取原付款状态',billing_update:'更新账单与税费'})
Object.assign(diagnosticLabels,{provider_error_type:'上游错误类型',provider_param:'被拒绝的参数名',provider_reason:'上游拒绝原因',request_kind:'请求环节',challenge_required:'上游要求安全验证',edge_request_id:'网关请求编号'})
Object.assign(diagnosticValues,{raw_card_api_restricted:'上游限制直接通过 API 提交卡号',secret_key_required:'该请求需要商户私钥权限',invalid_request_error:'请求参数或接口权限错误',card_error:'银行卡错误',api_error:'上游接口错误',authentication_error:'接口鉴权错误',permission_error:'接口权限错误',idempotency_error:'幂等请求冲突',rate_limit_error:'请求限流'})
Object.assign(requestLabels,{checkout_page:'读取结账页面',stripe_script:'读取 Stripe 脚本',stripe_frame:'读取 Stripe 框架资源',device_registration:'设备注册请求',telemetry:'遥测请求（可选）',card_metadata:'卡类型查询（可选）',elements_read:'读取付款组件会话',payment_approve:'批准原付款',renewal_update:'设置续费',merchant_prepare:'商户会话准备'})
Object.assign(diagnosticLabels,{required_step:'必要步骤',execution_environment:'请求执行环境',device_data_source:'设备数据来源',context_restored:'沿用恢复上下文',browser_profile:'原流程画像配置'})
Object.assign(diagnosticValues,{http_protocol:'HTTP 协议客户端',protocol_adapter:'协议适配器（非浏览器 SDK 实测）',payment_context_mismatch:'原交易上下文不完整或模式不符',stripe_resource_unavailable:'必要 Stripe 资源不可用'})
Object.assign(diagnosticValues,requestLabels)
Object.assign(diagnosticLabels,{stripe_api_version:'本次请求 API 版本'})
Object.assign(diagnosticValues,{invalid_api_version:'上游不接受指定的 API 版本'})
Object.assign(diagnosticLabels,{email_source:'账单邮箱来源'})
Object.assign(requestLabels,{direct_exit_probe:'对照检查本机出口（未使用订单代理）'})
Object.assign(diagnosticValues,{system_billing:'系统账单资料',subscription_account:'本次订阅账号邮箱'})
Object.assign(requestLabels,{merchant_return:'访问付款回跳页',renewal_read:'查询自动续费状态'})
Object.assign(diagnosticLabels,{response_content_type:'响应内容类型',response_error_code:'响应错误码',response_error_type:'响应错误类型',response_message:'错误说明（已脱敏）',response_detail:'错误详情（已脱敏）',response_title:'响应页面标题',response_summary:'响应摘要（已脱敏）',response_truncated:'响应超出记录上限',cf_ray:'网关请求编号',response_request_id:'上游请求编号',retrying:'将重试此查询',retry_wait_ms:'计划重试间隔',retry_wait_elapsed_ms:'实际等待时间'})
Object.assign(diagnosticLabels,{retry_number:'本单重试次数',retry_limit:'最大重试次数',retry_delay_seconds:'重试间隔（秒）',checkout_reused:'复用原结账链接'})
Object.assign(diagnosticLabels,{checkout_exit_code:'提链进程退出码'})
Object.assign(diagnosticValues,{go_checkout:'Go 提链程序'})
Object.assign(diagnosticLabels,{proxy_protocol:'本次代理协议',proxy_connect_ms:'连接代理耗时',proxy_tls_ms:'代理 TLS 握手耗时',proxy_tunnel_ms:'代理隧道协商耗时',proxy_connect_status:'代理 CONNECT 状态码',proxy_tunnel_established:'代理隧道已建立',connection_reused:'复用已有连接',connection_idle_ms:'连接复用前空闲时间',request_written:'请求已写出（不代表上游已处理）',response_started:'已收到响应字节',response_headers_received:'已完整收到响应头',response_status:'已收到的 HTTP 状态码',response_bytes_received:'已接收响应内容（字节）',request_timeout_ms:'本次请求超时预算',remaining_deadline_ms:'流程剩余时间',network_error_class:'网络错误分类',network_error_op:'失败的网络操作',timeout_source:'超时或中断来源'})
Object.assign(diagnosticValues,{tcp_connect:'建立 TCP 连接',tls_handshake:'目标 TLS 握手',proxy_tls:'代理 TLS 握手',proxy_tunnel:'代理隧道协商',dns_timeout:'域名解析超时',dns_failure:'域名解析失败',tls_certificate:'TLS 证书校验失败',canceled:'请求已取消',connection_reset:'连接被重置',connection_refused:'连接被拒绝',broken_pipe:'连接写入中断',network_unreachable:'网络或目标不可达',unexpected_eof:'响应提前中断',eof:'连接提前关闭',proxy_handshake:'代理隧道协商失败',network_other:'其他网络错误（未输出原文）',dial:'建立连接',read:'读取数据',write:'写入数据',flow_deadline:'付款后流程总时限耗尽',flow_canceled:'付款后流程已中断',request_deadline:'本次请求时限耗尽',transport_timeout:'底层网络超时',direct:'直连'})
const diagnosticText=(key:string,value:unknown)=>key==='network_stage'&&value==='dns'?'域名解析':key==='network_stage'&&value==='proxy_connect'?'连接代理':key==='response_error_code'?String(value):typeof value==='boolean'?(value?'是':'否'):key.endsWith('_ms')?`${value} 毫秒`:diagnosticValues[String(value)]||String(value)
const duration=(v:unknown)=>Number(v)>=1000?`${(Number(v)/1000).toFixed(1)} 秒`:`${Number(v)||0} 毫秒`
</script>
<template>
  <section class="payment-trace" aria-label="原始技术记录">
    <p v-if="events.some(e=>e.source==='business')" class="trace-hint">包含已保存的业务事件，已标注来源。历史记录未保存的请求状态码、单次耗时和重试次数不会补造。</p>
    <p v-if="!events.length" class="trace-empty">此订单尚无新版阶段记录，可查看下方已有业务记录。历史步骤不会补写为已执行。</p>
    <ol v-else>
      <li v-for="(e,i) in rows" :key="e.id||i" :class="e.displayState">
        <span class="trace-icon"><LoaderCircle v-if="e.spinning" class="spinning" :size="16"/><AlertTriangle v-else-if="['failed','review'].includes(e.state)" :size="16"/><FileText v-else-if="e.displayState==='recorded'" :size="15"/><CheckCircle2 v-else :size="16"/></span>
        <details class="trace-content">
          <summary class="trace-title">
            <span class="trace-primary"><b>{{eventLabel(e)}}</b><span class="trace-state">{{eventStatus(e)}}</span></span>
            <span class="trace-meta"><time :datetime="e.ended_at||e.started_at||e.created_at">{{e.ended_at?'结束':e.spinning?'开始':'记录'}} · {{date(e.ended_at||e.started_at||e.created_at)}}</time><span v-if="e.duration_ms!=null">耗时 {{duration(e.duration_ms)}}</span><span v-if="e.http_status" :class="{'http-error':e.http_status>=400}">HTTP {{e.http_status}}</span><span v-if="e.round">第 {{e.round}} 轮</span></span>
            <ChevronRight class="trace-chevron" :size="15"/>
          </summary>
          <div class="trace-body"><p v-if="e.started_at">开始 · {{date(e.started_at)}}<template v-if="e.ended_at">　结束 · {{date(e.ended_at)}}</template></p><details v-if="e.raw.length>1" class="raw-records"><summary>原始记录（{{e.raw.length}}）</summary><div v-for="record in e.raw" :key="record.id"><p>{{date(record.created_at)}} · {{record.source==='business'?'业务事件':'技术记录'}} · {{record.label}} · {{statusLabel[record.state]||record.state}}<template v-if="record.http_status"> · HTTP {{record.http_status}}</template><template v-if="record.elapsed_ms"> · {{duration(record.elapsed_ms)}}</template><template v-if="record.request_id"> · 关联编号 {{record.request_id}}</template><br/>{{record.description}}</p><dl class="trace-diagnostics"><template v-for="(value,key) in record.diagnostics||{}" :key="key"><dt>{{diagnosticLabels[String(key)]||key}}</dt><dd>{{diagnosticText(String(key),value)}}</dd></template></dl></div></details>
            <p v-if="e.http_status||e.request_id" class="mono">{{e.http_status?'响应 '+e.http_status:''}} {{e.request_id?' · 关联编号 '+e.request_id:''}}</p>
            <p v-if="e.description">{{e.description}}</p>
            <dl v-if="e.diagnostics&&Object.keys(e.diagnostics).length" class="trace-diagnostics"><template v-for="(value,key) in e.diagnostics" :key="key"><dt>{{diagnosticLabels[String(key)]||key}}</dt><dd>{{diagnosticText(String(key),value)}}</dd></template></dl>
            <p v-if="!e.http_status&&!e.request_id&&!e.description&&!Object.keys(e.diagnostics||{}).length">暂无补充详情。</p>
          </div>
        </details>
      </li>
    </ol>
  </section>
</template>
<style scoped>
.payment-trace{margin:22px 0;padding:22px;background:#f7f9fc;border:1px solid #e3e9f0;border-radius:14px}.trace-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.trace-heading h3{margin:6px 0}.trace-rounds{display:flex;align-items:center;gap:6px;color:#53647b;font-size:12px;white-space:nowrap}.trace-hint,.trace-empty{color:#77849a;font-size:12px;line-height:1.7}.payment-trace ol{list-style:none;margin:20px 0 0;padding:0}.payment-trace li{display:flex;gap:12px;position:relative;padding:0 0 18px}.payment-trace li:not(:last-child):before{content:'';position:absolute;left:12px;top:25px;bottom:0;width:1px;background:#dbe4ee}.trace-icon{width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:#e5edf8;color:#496c9a;flex-shrink:0}.completed .trace-icon{background:#e1f3e9;color:#268757}.failed .trace-icon,.review .trace-icon{background:#fff0dd;color:#b87014}.trace-title{display:flex;align-items:center;gap:9px;flex-wrap:wrap;font-size:13px}.trace-title small,.trace-content time{font-size:11px;color:#7c899c}.trace-content p{margin:7px 0;color:#65738b;font-size:12px;line-height:1.7}.trace-state{font-size:11px;color:#526880;background:#e8edf3;padding:2px 7px;border-radius:4px}.failed .trace-state,.review .trace-state{color:#a36215;background:#fff0dd}.trace-content{flex:1;min-width:0}.trace-title{list-style:none;cursor:pointer;min-height:26px}.trace-title::-webkit-details-marker{display:none}.trace-title:focus-visible{outline:2px solid #496c9a;outline-offset:4px;border-radius:4px}.trace-content time{white-space:nowrap}.trace-chevron{margin-left:auto;flex-shrink:0;transition:transform .15s}.trace-content[open] .trace-chevron{transform:rotate(90deg)}.trace-body{padding:5px 0 2px}.trace-diagnostics{grid-template-columns:auto minmax(0,1fr)}@media(max-width:650px){.payment-trace{padding:15px}.trace-heading{align-items:flex-start;flex-direction:column}}
.trace-diagnostics{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;margin:8px 0;font-size:11px;color:#65738b}.trace-diagnostics dd{margin:0;overflow-wrap:anywhere}

.trace-title{display:grid;grid-template-columns:minmax(0,1fr) 18px;gap:6px 12px;align-items:start}.trace-primary{display:flex;align-items:center;gap:10px;flex-wrap:wrap;grid-column:1}.trace-primary b{line-height:1.6}.trace-meta{grid-column:1;display:flex;align-items:center;gap:7px 16px;flex-wrap:wrap;font-size:11px;color:#7c899c;line-height:1.8}.trace-meta .http-error{color:#b45326;font-weight:600}.trace-chevron{grid-column:2;grid-row:1/3;align-self:center}.trace-state{white-space:nowrap}.trace-body{margin-top:12px;padding:12px 14px;border:1px solid #e2e9ef;border-radius:8px;background:white}.raw-records{padding:10px 0}.raw-records>summary{font-size:12px;cursor:pointer;color:#536b80}.raw-records>div{padding:8px 0;border-bottom:1px solid #edf1f4}.raw-records>div:last-child{border:0}.recorded .trace-icon{background:#edf1f4;color:#7b8c98}.running .trace-icon{background:#e5edf8;color:#496c9a}.trace-diagnostics dt{max-width:170px;overflow-wrap:anywhere}@media(max-width:500px){.trace-meta{gap:4px 10px}.trace-diagnostics{grid-template-columns:1fr}.trace-diagnostics dd{margin-bottom:6px}.payment-trace{padding:12px}.trace-title{gap:4px 6px}}
</style>
